33	      --color-mint-rgb: 149, 225, 211;
34	      --color-purple: #d946ef;
35	      --color-purple-rgb: 217, 70, 239;
36	      --color-orange: #ff9500;
37	      --color-orange-rgb: 255, 149, 0;
38	    }
39	
40	    * {
41	      margin: 0;
42	      padding: 0;
43	      box-sizing: border-box;
44	    }
45	    html, body {
46	      height: 100%;
47	    }
48	    body {
49	      display: flex;
50	      flex-direction: column;
51	      justify-content: center;
52	      align-items: center;
53	      gap: 20px;
54	      background: linear-gradient(135deg, #5f6fd1 0%, #6b3fa0 100%);
55	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
56	      color: var(--color-white);
57	      font-size: 14px;
