90	    circle {
91	      fill: var(--color-white);
92	      stroke: rgba(255, 255, 255, 0.25);
93	      stroke-width: 1.5;
94	      animation: pulse var(--pulse-duration) ease-in-out infinite;
95	      filter: drop-shadow(0 20px 40px var(--shadow-color));
96	      transition: fill 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), r 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), stroke 0.35s ease, filter 0.35s ease;
97	    }
98	    .circle-container:is(:hover, :focus-visible) circle {
99	      fill: #e8f4f8;
100	      r: 205;
