216	    .control-btn:disabled {
217	      opacity: 0.5;
218	      cursor: not-allowed;
219	    }
220	    @keyframes pulse {
221	      0%, 100% { r: 200; opacity: 0.96; }
222	      50% { r: 202; opacity: 1; }
223	    }
224	    @keyframes pulse-active {
225	      0% { r: 200; }
226	      50% { r: 208; }
227	      100% { r: 200; }
228	    }
229	    @keyframes fadeIn {
230	      from { opacity: 0; transform: scale(0.95); }
231	      to { opacity: 1; transform: scale(1); }
232	    }
233	    @keyframes colorShift {
234	      0% { r: 200; filter: saturate(0.8) brightness(0.92) hue-rotate(0deg); }
235	      50% { r: 212; filter: saturate(1.3) brightness(1.12) hue-rotate(10deg); }
236	      100% { r: 200; filter: saturate(1) brightness(1) hue-rotate(0deg); }
237	    }
238	    .circle-container.color-shifting circle {
239	      animation: colorShift 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
240	    }
241	    .keyboard-hint {
242	      font-size: 11px;
243	      opacity: 0.9;
244	      margin-top: 2px;
245	      letter-spacing: 0.2px;
246	      transition: opacity var(--transition-normal);
247	      font-weight: 500;
248	      color: rgba(255, 255, 255, 0.95);
249	    }
250	    .keyboard-hint kbd {
251	      background: rgba(255, 255, 255, 0.15);
252	      border: 1.5px solid rgba(255, 255, 255, 0.35);
253	      border-radius: 4px;
254	      padding: 3px 8px;
255	      font-family: 'Monaco', 'Courier New', monospace;
256	      font-size: 10px;
