322	      }
323	      .keyboard-hint kbd {
324	        padding: 3px 7px;
325	        font-size: 9px;
326	      }
327	    }
328	    @media (prefers-reduced-motion: reduce) {
329	      * {
330	        animation: none !important;
331	        transition: none !important;
332	      }
333	    }
334	    @supports (backdrop-filter: blur(0)) {
335	      .control-btn {
336	        background: rgba(255, 255, 255, 0.1);
337	      }
338	    }
339	    @supports not (backdrop-filter: blur(0)) {
340	      .control-btn {
341	        background: rgba(0, 0, 0, 0.3);
342	      }
343	    }
344	    @media (prefers-color-scheme: light) {
345	      body {
346	        background: linear-gradient(135deg, #a8b5e8 0%, #c99fe6 100%);
347	      }
348	      circle {
349	        fill: #ffffff;
350	        stroke: rgba(0, 0, 0, 0.15);
351	        filter: drop-shadow(0 8px 20px rgba(0, 0, 0, 0.1));
352	      }
353	      .circle-container:is(:hover, :focus-visible) circle {
354	        fill: #f8f8f8;
355	        stroke: rgba(0, 0, 0, 0.25);
356	        filter: drop-shadow(0 10px 30px rgba(0, 0, 0, 0.15));
357	      }
358	      .control-btn {
359	        background: rgba(255, 255, 255, 0.35);
