361	        color: rgba(0, 0, 0, 0.9);
362	      }
363	      .control-btn:hover {
364	        background: rgba(255, 255, 255, 0.5);
365	        border-color: rgba(255, 255, 255, 0.9);
366	        color: rgba(0, 0, 0, 0.95);
367	        box-shadow: 0 8px 16px rgba(0, 0, 0, 0.15);
368	      }
369	      .control-btn:active {
