388	        color: rgba(0, 0, 0, 0.85);
389	      }
390	    }
391	  </style>
392	</head>
393	<body>
394	  <main>
395	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-describedby="hint-text">
396	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
397	        <circle cx="200" cy="200" r="200"/>
398	      </svg>
399	    </button>
400	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
401	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
402	    <div class="controls" role="group" aria-label="Circle controls">
403	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
404	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
405	    </div>
406	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
407	  </main>
408	
409	  <script defer>
410	    (() => {
411	      const COLORS = [
412	        { class: 'default', name: 'Default White' },
413	        { class: 'color-mode-1', name: 'Pink' },
414	        { class: 'color-mode-2', name: 'Teal' },
415	        { class: 'color-mode-3', name: 'Mint' },
416	        { class: 'color-mode-4', name: 'Purple' },
417	        { class: 'color-mode-5', name: 'Orange' }
418	      ];
419	
420	      const CONFIG = {
421	        storageKey: 'circle-state',
422	        tapDelay: 300,
423	        colorShiftDuration: 500,
424	        saveDebounceDuration: 100,
425	        isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0
426	      };
427	
428	      const el = {
429	        circle: document.getElementById('decorative-circle'),
430	        hint: document.getElementById('hint-text'),
431	        modeIndicator: document.getElementById('mode-indicator'),
432	        cycleBtn: document.getElementById('cycle-btn'),
433	        resetBtn: document.getElementById('reset-btn')
434	      };
435	
436	      let state = { active: false, colorMode: 0 };
437	      let tapCount = 0;
438	      let tapTimeout = null;
439	      let animatingColorShift = false;
440	      let saveTimeout = null;
441	
442	      const getColorClass = (mode) => COLORS[mode % COLORS.length].class;
443	      const getColorName = (mode) => COLORS[mode % COLORS.length].name;
444	
445	      const storage = {
446	        save() {
447	          clearTimeout(saveTimeout);
448	          saveTimeout = setTimeout(() => {
449	            try {
450	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
451	            } catch (e) {
452	              if (e.name === 'QuotaExceededError') {
453	                console.warn('Storage quota exceeded');
454	              }
455	            }
456	          }, CONFIG.saveDebounceDuration);
457	        },
458	        load() {
459	          try {
460	            const saved = localStorage.getItem(CONFIG.storageKey);
461	            if (saved) {
462	              const parsed = JSON.parse(saved);
463	              if (parsed?.active !== undefined && parsed?.colorMode !== undefined) {
464	                state = parsed;
465	              }
466	            }
467	          } catch (e) {
468	            // Silent failure - use default state
469	          }
470	        }
471	      };
472	
473	      const updateClasses = () => {
474	        const colorClasses = COLORS.map(m => m.class);
475	        el.circle.classList.remove('active', ...colorClasses);
476	        el.circle.setAttribute('aria-pressed', state.active);
477	        if (state.active) el.circle.classList.add('active');
478	        if (state.colorMode > 0) el.circle.classList.add(getColorClass(state.colorMode));
479	      };
480	
481	      const updateUI = () => {
482	        const hint = CONFIG.isTouch
483	          ? (state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
484	          : (state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle');
485	        el.hint.textContent = hint;
486	
487	        const showMode = state.active && state.colorMode > 0;
488	        el.modeIndicator.classList.toggle('visible', showMode);
489	        if (showMode) {
490	          el.modeIndicator.textContent = `◆ ${getColorName(state.colorMode).toUpperCase()}`;
491	        }
492	      };
493	
494	      const applyState = () => {
495	        updateClasses();
496	        updateUI();
497	      };
498	
499	      const toggleActive = () => {
500	        state.active = !state.active;
501	        applyState();
502	        storage.save();
503	      };
504	
505	      const cycleColor = () => {
506	        if (animatingColorShift) return;
507	        animatingColorShift = true;
508	        state.colorMode = (state.colorMode + 1) % COLORS.length;
509	        state.active = true;
510	        el.circle.classList.add('color-shifting');
511	        setTimeout(() => {
512	          el.circle.classList.remove('color-shifting');
513	          animatingColorShift = false;
514	        }, CONFIG.colorShiftDuration);
515	        applyState();
516	        storage.save();
517	      };
518	
519	      const resetState = () => {
520	        state = { active: false, colorMode: 0 };
521	        applyState();
522	        storage.save();
523	      };
524	
525	      const handleTouchEnd = () => {
526	        tapCount++;
527	        clearTimeout(tapTimeout);
528	        if (tapCount === 1) {
529	          tapTimeout = setTimeout(() => {
530	            if (tapCount === 1) toggleActive();
531	            tapCount = 0;
532	          }, CONFIG.tapDelay);
533	        } else if (tapCount === 2) {
534	          cycleColor();
535	          tapCount = 0;
536	        }
537	      };
538	
539	      const keyHandlers = {
540	        ' ': toggleActive,
541	        'enter': toggleActive,
542	        'escape': resetState,
543	        'c': cycleColor,
544	        'r': resetState
545	      };
546	
547	      const handleKeyDown = (e) => {
548	        const handler = keyHandlers[e.key.toLowerCase()];
549	        if (handler) {
550	          e.preventDefault();
551	          handler();
552	        }
553	      };
554	
555	      const initListeners = () => {
556	        if (CONFIG.isTouch) {
557	          el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
558	        } else {
559	          el.circle.addEventListener('click', toggleActive, { passive: true });
560	          el.circle.addEventListener('dblclick', cycleColor, { passive: true });
561	        }
562	        el.circle.addEventListener('blur', () => {
563	          tapCount = 0;
564	          clearTimeout(tapTimeout);
565	        });
566	        document.addEventListener('keydown', handleKeyDown);
567	        el.cycleBtn.addEventListener('click', cycleColor, { passive: true });
568	        el.resetBtn.addEventListener('click', resetState, { passive: true });
569	      };
570	
571	      const initApp = () => {
572	        storage.load();
573	        applyState();
574	        initListeners();
575	        el.circle.focus();
576	      };
577	
578	      const ensureSave = () => {
579	        clearTimeout(saveTimeout);
580	        try {
581	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
582	        } catch (e) {
583	          // Silently fail on storage errors during page hide
584	        }
585	      };
586	
587	      if (document.readyState === 'loading') {
588	        document.addEventListener('DOMContentLoaded', initApp);
589	      } else {
590	        initApp();
591	      }
592	
593	      window.addEventListener('pagehide', ensureSave);
594	    })();
595	  </script>
596	</body>
597	</html>
