file.content:
svg {
  width: min(400px, 80vw);
  height: min(400px, 80vw);
  display: block;
  animation: fadeIn var(--transition-slow), hintBounce 2.5s ease-in-out 1s 1;
}
circle {
  fill: var(--color-white);
  stroke: rgba(255, 255, 255, 0.25);
  stroke-width: 1.5;
  animation: pulse var(--pulse-duration) ease-in-out infinite;
  filter: drop-shadow(0 20px 40px var(--shadow-color));
  transition: fill 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), r 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), stroke 0.35s ease, filter 0.35s ease, opacity 0.35s ease;
}
.circle-container:is(:hover, :focus-visible) circle {
  fill: #e8f4f8;
  r: 205;
  stroke: rgba(255, 255, 255, 0.5);
  filter: drop-shadow(0 20px 50px rgba(255, 255, 255, 0.2));
}
.circle-container.active:not([class*="color-mode-"]) circle {
  fill: var(--color-gold);
  stroke: rgba(255, 215, 0, 0.4);
  animation: pulse-active 0.6s ease-in-out;
  filter: drop-shadow(0 20px 50px rgba(255, 215, 0, 0.6));
  r: 200;
}

.circle-container.color-mode-1 { --mode-color: var(--color-pink); --mode-rgb: var(--color-pink-rgb); }
.circle-container.color-mode-2 { --mode-color: var(--color-teal); --mode-rgb: var(--color-teal-rgb); }
.circle-container.color-mode-3 { --mode-color: var(--color-mint); --mode-rgb: var(--color-mint-rgb); }
.circle-container.color-mode-4 { --mode-color: var(--color-purple); --mode-rgb: var(--color-purple-rgb); }
.circle-container.color-mode-5 { --mode-color: var(--color-orange); --mode-rgb: var(--color-orange-rgb); }

[class*="color-mode-"] circle {
  fill: var(--mode-color);
  stroke: rgba(var(--mode-rgb), 0.35);
  filter: drop-shadow(0 20px 50px rgba(var(--mode-rgb), 0.4));
}
[class*="color-mode-"]:is(:hover, :focus-visible) circle {
  stroke: rgba(var(--mode-rgb), 0.55);
  filter: drop-shadow(0 20px 55px rgba(var(--mode-rgb), 0.5));
}
[class*="color-mode-"].active circle {
  animation: pulse-active 0.6s ease-in-out;
  r: 200;
  filter: drop-shadow(0 20px 50px rgba(var(--mode-rgb), 0.6));
}

.hint {
  font-size: 13px;
  opacity: 1;
  transition: opacity 0.2s ease;
  letter-spacing: 0.4px;
  max-width: 95%;
  line-height: 1.5;
  margin-top: 8px;
  position: relative;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.6);
  font-weight: 600;
  color: rgba(255, 255, 255, 0.99);
}

.mode-indicator {
  font-size: 11px;
  opacity: 0;
  margin-top: 10px;
  letter-spacing: 2px;
  text-transform: uppercase;
  transition: opacity 0.25s cubic-bezier(0.34, 1.56, 0.64, 1), transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
  height: 20px;
  font-weight: 800;
  transform: scale(0.85) translateY(10px);
  color: rgba(255, 255, 255, 0.98);
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
  pointer-events: none;
}
.mode-indicator.visible {
  opacity: 1;
  transform: scale(1) translateY(0);
}

.controls {
  display: flex;
  gap: 12px;
  margin-top: 6px;
  flex-wrap: wrap;
  justify-content: center;
  width: 100%;
}

.control-btn {
  padding: 12px 30px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  background: rgba(255, 255, 255, 0.18);
  color: var(--color-white);
  border: 1.5px solid rgba(255, 255, 255, 0.35);

